mapper.select:
select fe.employee_code as judge_member_code
from fnd_employee fe,
sys_user su,
sys_user_allocation sua,
fnd_employee_assigns fea
where su.USER_ID = sua.user_id
and su.USER_NAME = #{judgeMemberCode}
and fe.employee_id = fea.employee_id
and fea.employee_assign_id = sua.employee_assign_id


        and sua.company_id = #{companyId}


        and sua.company_id = #{request.companyId}

SELECT judge_id
FROM
act_meeting_judge
WHERE
1 = 1

    and process_instance_id = #{processInstanceId}


    and meeting_id = #{meetingId}


    and judge_member_code = #{judgeMemberCode}

select amj.judge_id, amj.judge_member_code, (select fe.name from fnd_employee fe where amj.judge_member_code = fe.employee_code) as judge_member_name, CASE amj.judge_suggestion WHEN 'PART_AGREE' THEN '有条件同意' WHEN 'AGREE' THEN '同意' ELSE '不同意' END as judge_suggestion, amj.judge_comment, amj.creation_date as judge_date, amj.to_be_satisfied_condition from act_meeting_judge amj WHERE 1 = 1
and process_instance_id = #{processInstanceId}
and amj.judge_suggestion = 'PART_AGREE'
